import { products, activities, stories } from './content.js';
import { config } from './config.js';

const $ = (selector, root = document) => root.querySelector(selector);
const main = $('#main-content');
const modal = $('#modal');
const cartDialog = $('#cart');
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const asset = file => `./assets/${file}`;
const money = value => `¥${Number(value).toFixed(2)}`;
const searchIcon = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6" stroke="currentColor" stroke-width="1.5"/><path d="m15 15 5 5" stroke="currentColor" stroke-width="1.5"/></svg>';
const dateText = value => new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Shanghai'}).format(new Date(`${value}T12:00:00+08:00`));
const today = () => new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const addDays = (date, days) => {const value=new Date(`${date}T12:00:00+08:00`);value.setUTCDate(value.getUTCDate()+days);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(value);};
let route='home', shopCategory='全部文创', shopQuery='', shopSort='featured', season='spring', storyCategory='全部足迹';
let wizard=null, currentProduct=null, productVariant='', productQuantity=1, checkout=null, lastDraft=null, toastTimer;
let cart=[];
try {
  const saved=JSON.parse(localStorage.getItem('reed-flame-cart-v1') || '[]');
  if(Array.isArray(saved)) cart=saved.filter(item => products.some(p=>p.id===item.id && p.variants.includes(item.variant)) && Number.isInteger(item.quantity) && item.quantity>0 && item.quantity<=99).slice(0,30);
} catch { cart=[]; }
function saveCart(){try{localStorage.setItem('reed-flame-cart-v1',JSON.stringify(cart));}catch{}updateCartBadge();}
function updateCartBadge(){const count=cart.reduce((sum,item)=>sum+item.quantity,0);const badge=$('.cart-count');badge.textContent=count;badge.hidden=!count;$('.cart-toggle').setAttribute('aria-label',`打开购物袋，${count} 件商品`);}
function toast(message){clearTimeout(toastTimer);const node=$('#toast');node.textContent=message;node.classList.add('visible');toastTimer=setTimeout(()=>node.classList.remove('visible'),3500);}
function openModal(title,content){modal.innerHTML=`<header class="modal-header"><h2 id="modal-title" tabindex="-1">${escape(title)}</h2><button class="close-modal" data-close="modal" aria-label="关闭弹窗">×</button></header><div class="modal-body">${content}</div>`;if(!modal.open)modal.showModal();else $('#modal-title').focus({preventScroll:true});modal.scrollTop=0;}
function priceLabel(){return config.mode==='demo'?'参考价':'售价';}
function productCard(product){return `<article class="product-card"><button class="product-image-button" data-product="${product.id}" aria-label="查看${product.name}"><img src="${asset(product.image)}" alt="${product.name}，文创设计展示" loading="lazy"><span class="product-tag">${product.tag}</span></button><h3><button data-product="${product.id}">${product.name}</button></h3><p>${product.subtitle}</p><div class="product-bottom"><span class="price">¥${product.price}<small>${priceLabel()}</small></span><button class="add-circle" data-product="${product.id}" aria-label="选择${product.name}款式并加入购物袋">+</button></div></article>`;}
function storyCard(story){return `<article class="story-card"><button data-story="${story.id}" aria-label="阅读：${story.title}"><img src="${asset(story.image)}" alt="${story.title}" loading="lazy"><span class="mini-label">${story.category}</span><h3>${story.title}</h3><p>${story.excerpt}</p><span class="arrow-link">阅读故事 <span aria-hidden="true">↗</span></span></button></article>`;}
function pageHeading(title,description,english){return `<div class="page-heading"><div class="container"><div class="breadcrumb"><a href="#home">首页</a><span>/</span>${title}</div><div class="eyebrow">${english}</div><h1>${title}</h1><p>${description}</p></div></div>`;}
function homePage(){return `
  <section class="hero container" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">沙家浜 · 红色文化美育</p><h1 id="hero-title">从芦荡出发，<br>让红色文化<br><em>走进生活。</em></h1><p class="hero-desc">在一段京韵里读懂历史，在一次研学中发现美。<br>让沙家浜的故事，成为新一代可以感受、<br class="desktop-break">参与和表达的文化记忆。</p><div class="hero-actions"><a class="button primary" href="#activities">开启美育之旅 <span aria-hidden="true">↗</span></a><a class="button" href="#shop">探索京韵文创 <span aria-hidden="true">→</span></a></div><div class="hero-footnote"><span></span><span>红色文化 / 江南水乡 / 青年传承</span></div></div><figure class="hero-visual"><img src="${asset('wetland.webp')}" alt="沙家浜芦荡水乡：小桥、舟船与夕阳" fetchpriority="high"><span class="hero-seal" aria-hidden="true">以美润心</span><span class="hero-quote" aria-hidden="true">一湾芦风起<br>万缕薪火传</span><figcaption><span>江南芦荡 · 戏韵悠长</span><span class="english">SHAJIABANG</span></figcaption></figure></section>
  <div class="container"><div class="principles"><div class="principle"><span class="principle-number">01</span><div><strong>感知美</strong><small>在自然与戏曲中发现美</small></div></div><div class="principle"><span class="principle-number">02</span><div><strong>理解美</strong><small>在红色故事中读懂精神</small></div></div><div class="principle"><span class="principle-number">03</span><div><strong>表达美</strong><small>在创作与参与中传承文化</small></div></div></div></div>
  <section class="section container"><div class="section-heading"><div><p class="eyebrow">EXPERIENCE</p><h2>把故事，变成亲身经历</h2><p>从角色代入到四季研学，每一次参与都有新的发现。</p></div><a href="#activities" class="arrow-link">全部活动 <span aria-hidden="true">↗</span></a></div><div class="experience-grid"><article class="experience-card"><img src="${asset('theatre.webp')}" alt="沙家浜春来茶馆情景剧设计画面" loading="lazy"><div class="experience-copy"><span class="mini-label">沉浸式红色剧本杀</span><h3>芦荡茶影 · 春来谜局</h3><p>走进春来茶馆，在角色与线索中感受烽火年代的选择。</p><div class="meta"><span>90–120 分钟</span><span>学生 / 成人</span></div><button class="text-link arrow-link" data-book="script">查看并预约 <span aria-hidden="true">↗</span></button></div></article><article class="experience-card"><img src="${asset('youth.webp')}" alt="沙家浜青年学习社区" loading="lazy"><div class="experience-copy"><span class="mini-label">四季红色研学课程</span><h3>跟着四季，学习美</h3><p>春听京韵，夏绘脸谱，秋探非遗，冬叙红色故事。</p><div class="meta"><span>单日营 / 系列课</span><span>四季主题</span></div><a class="arrow-link" href="#activities" data-section="season-courses">探索研学课程 <span aria-hidden="true">↗</span></a></div></article></div></section>
  <section class="section shop-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">CULTURAL COLLECTION</p><h2>让京韵，留在日常</h2><p>一份文创，一段故事，也是一份关于美的心意。</p></div><a href="#shop" class="arrow-link">逛逛商城 <span aria-hidden="true">↗</span></a></div><div class="product-grid">${products.map(productCard).join('')}</div><p class="shop-note">${config.mode==='demo'?'文创产品展示，价格仅作流程演示；暂不进行真实收款或发货。':'商品规格和交付安排以订单服务确认信息为准。'}</p></div></section>
  <section class="section container"><div class="project-teaser"><figure class="project-photo"><img src="${asset('team.webp')}" alt="项目团队在沙家浜革命历史纪念墙前合影" loading="lazy"><figcaption>从田野到课堂 · 项目团队实践记录</figcaption></figure><div><p class="eyebrow">ABOUT THE PROJECT</p><h2>芦荡薪火，<br>以美润心。</h2><p>以沙家浜的红色历史、京剧艺术与自然生态为起点，探索青年愿意参与、能够表达的美育实践。通过 <math aria-label="五加 X"><mn>5</mn><mo>+</mo><mi>X</mi></math> 红色美育浸润模式，连接高校、景区、社区与在地文化工作者。</p><div class="season-strip" aria-label="春夏秋冬四季课程"><span>春</span><span>夏</span><span>秋</span><span>冬</span></div><a href="#project" class="arrow-link">走近我们的项目 <span aria-hidden="true">↗</span></a></div></div></section>
  <section class="cta-band"><div class="container cta-inner"><div><h2>把下一次相聚，交给一段有意义的旅程。</h2><p>学生专场、社区体验、四季研学，让美育在参与中发生。</p></div><button class="button white" data-book="">选择我的体验 <span aria-hidden="true">↗</span></button></div></section>
  <section class="section container"><div class="section-heading"><div><p class="eyebrow">OUR FOOTPRINTS</p><h2>每一步，都有回响</h2><p>记录田野里的对话、课堂里的发现与青年自己的表达。</p></div><a href="#stories" class="arrow-link">美育足迹 <span aria-hidden="true">↗</span></a></div><div class="stories-grid">${stories.map(storyCard).join('')}</div></section>`;}
function shopPage(){return `${pageHeading('文创商城','让沙家浜的故事留在书页、服饰与礼物里，把一份文化记忆带回日常。','CULTURAL COLLECTION')}<section class="container page-content"><div class="catalog-toolbar"><div class="pills" aria-label="商品分类">${['全部文创','红色京剧文创','研学周边','体验伴手礼'].map(category=>`<button class="pill" data-category="${category}" aria-pressed="${shopCategory===category}">${category}</button>`).join('')}</div><div class="search-tools"><label class="search-box"><span class="visually-hidden">搜索商品</span><input id="shop-search" type="search" value="${escape(shopQuery)}" placeholder="搜索文创好物" aria-label="搜索商品">${searchIcon}</label><select id="shop-sort" aria-label="商品排序"><option value="featured" ${shopSort==='featured'?'selected':''}>推荐排序</option><option value="low" ${shopSort==='low'?'selected':''}>价格从低到高</option><option value="high" ${shopSort==='high'?'selected':''}>价格从高到低</option></select></div></div><div class="catalog-meta"><span id="result-count" aria-live="polite"></span><span>${config.mode==='demo'?'参考价格 · 商品与款式为设计展示':'商品规格及交付以正式订单为准'}</span></div><div class="product-grid" id="catalog-grid"></div><p class="shop-note">${config.mode==='demo'?'当前为商城演示版。可选择款式、加入购物袋并导出订单草稿，订单不会发送至运营方。':'下单后请按订单服务提示确认库存、配送和付款。'}</p></section>`;}
function renderCatalog(){let filtered=products.filter(product=>(shopCategory==='全部文创'||product.categories.includes(shopCategory)) && `${product.name} ${product.subtitle} ${product.categories.join(' ')}`.includes(shopQuery.trim()));if(shopSort==='low')filtered.sort((a,b)=>a.price-b.price);if(shopSort==='high')filtered.sort((a,b)=>b.price-a.price);$('#result-count').textContent=`共 ${filtered.length} 件文创`;$('#catalog-grid').innerHTML=filtered.length?filtered.map(productCard).join(''):'<div class="empty-state"><h3>还没有找到这件好物</h3><p>试试其他关键词，或看看全部文创。</p><button class="button light" data-reset-search>查看全部文创</button></div>';}
function activitiesPage(){const script=activities[0];return `${pageHeading('活动预约','在角色里理解历史，在四季中感受美。选择适合自己的方式，开启一段沙家浜美育之旅。','LEARN THROUGH EXPERIENCE')}<section class="container page-content"><article class="activity-feature"><img src="${asset(script.image)}" alt="红色叙事剧本杀春来茶馆场景"><div><span class="mini-label">沉浸式红色剧本杀</span><h2>${script.name}</h2><div class="chips"><span class="chip">学生专场</span><span class="chip">成人社区场</span><span class="chip">5 人一组</span></div><p>${script.description}</p><div class="meta"><span>90–120 分钟</span><span>角色演绎 · 合作推理</span></div><span class="price">¥${script.price}<small>${priceLabel()} / 人</small></span><div class="feature-actions"><button class="button primary" data-book="script">查看课程并预约 <span aria-hidden="true">↗</span></button><button class="button light" data-course="script">美育目标</button></div></div></article><div class="season-heading" id="season-courses"><div><p class="eyebrow">FOUR SEASONS</p><h2>四季有美，四季有学</h2><p>单日营轻松体验，系列课持续成长。</p></div></div><div class="pills" aria-label="四季研学主题">${activities.slice(1).map(activity=>`<button class="pill" data-season="${activity.id}" aria-pressed="${season===activity.id}">${activity.season} · ${activity.name}</button>`).join('')}</div><div id="season-panel"></div><div class="process-strip" aria-label="预约流程">${['选择项目','查看简介与目标','选择时间','填写报名信息','确认与提交'].map((label,index)=>`<div><b>0${index+1}</b><span>${label}</span></div>`).join('')}</div><div class="notice">${config.mode==='demo'?'当前为预约流程演示，排期与费用均为示例。填写后可生成并下载预约草稿；正式场次、活动地点、带队安排和支付方式待运营方公布。':'请选择已公布场次。预约是否成立，以运营方返回的确认结果为准。'}</div><details><summary>学生专场与成人社区场有什么区别？</summary><p>学生专场侧重故事理解、协作与创意表达；成人社区场侧重角色共情与交流。具体适龄要求、带队和现场安排需由运营方确认。</p></details><details><summary>单日营和系列课如何选择？</summary><p>单日营适合初次体验。系列课按所选季节主题分多次学习，延续知识、体验、创作与分享环节。演示版暂以 4 次主题课展示，正式日期与时长以运营方公布为准。</p></details><details><summary>可以直接付款或获得预约名额吗？</summary><p>${config.mode==='demo'?'当前尚未接入正式预约与支付服务，不收款、不锁定名额。生成的文件是预约意向草稿。正式上线后，系统将由预约服务确认场次和费用。':'提交后系统会返回预约状态；只有服务确认的订单才代表已成功预约。'}</p></details></section>`;}
function renderSeason(){const activity=activities.find(item=>item.id===season);$('#season-panel').innerHTML=`<article class="season-panel"><img src="${asset(activity.image)}" alt="${activity.eyebrow}主题配图"><div><span class="english muted">${activity.english} / ${activity.season}日主题</span><h3>${activity.name}</h3><div class="chips"><span class="chip">${activity.theme}</span><span class="chip">单日营 / 系列课</span><span class="chip">${activity.duration}</span></div><p>${activity.description}</p><ul class="learning-goals">${activity.goals.map(goal=>`<li>${goal}</li>`).join('')}</ul><button class="button primary" data-book="${activity.id}">查看课程并预约 <span aria-hidden="true">↗</span></button></div></article>`;}
function projectPage(){return `${pageHeading('走近芦荡薪火','以红色文化浸润青年传承，把江南水乡与戏曲艺术转化为可感知、可参与、可表达的美育实践。','ABOUT REED & FLAME')}<div class="container page-content"><section class="project-intro"><div class="prose"><p class="eyebrow">我们的起点</p><h2>让沙家浜的文化资源，<br>成为青年的美育经历。</h2><p>项目立足沙家浜，将红色历史、京剧艺术、自然生态与在地生活相连接。围绕青年参与不深、体验较浅、表达不足与校地衔接等问题，探索从调研诊断到课程设计、再到场景实践的路径。</p><p>以“感知美—理解美—表达美”为线索，让青年通过角色代入、动手创作与故事讲述，建立对红色文化的理解与情感连接。</p></div><img src="${asset('cover.webp')}" alt="芦荡薪火 · 以美润心"></section>
  <section class="content-block prose"><h2>从问题出发，回到真实的参与</h2><p>沙家浜兼具革命历史、戏曲艺术与精神教育价值，但文化知名度尚未充分转化为主动研学、完整欣赏与深入理解。项目通过问卷、访谈与实地观察，关注青年需求、产品供给、传播表达和协同机制。</p><p>从课堂仿真教学和数字叙事案例中，团队获得两点启发：把资源转化为可学习的课程场景，并通过青年愿意参与的数字内容持续连接体验。</p><details><summary>政策背景与理论依据</summary><p>项目围绕新时代学校美育、学校美育浸润行动与江苏文化旅游高质量发展等政策方向，以美育人、课程浸润和校地协同为路径，推动红色文化与青年美育实践相结合。</p></details></section>
  <section class="content-block"><h2>四个视角，理解参与与传播</h2><div class="theory-grid"><article class="theory-card"><h3>S–O–R 理论</h3><p>从外部场景、内在感受与行为反应理解参与，优化青年美育输入场景。</p></article><article class="theory-card"><h3>编码与解码</h3><p>重构红色故事的表达方式，让内容与青年理解习惯相连接。</p></article><article class="theory-card"><h3>用户行为</h3><p>增加沉浸体验与创作实践，形成参与、表达和反馈的循环。</p></article><article class="theory-card"><h3>文旅社会治理</h3><p>连接高校、景区、社区与在地文化资源，探索共建共享。</p></article></div></section>
  <section class="content-block"><h2><math aria-label="五加 X"><mn>5</mn><mo>+</mo><mi>X</mi></math> 红色美育浸润模式</h2><p class="muted">五个创新产品，连接多元合作主体，让美育从课堂走向生活。</p><div class="five-grid" style="margin-top:23px">${[['01','美育服务平台','汇聚红色艺术资源，连接内容、课程与文创。'],['02','红色美育教育产品','以脸谱书签、丝巾、礼盒与手办承载日常文化体验。'],['03','四季美育课程','连接自然与人文，形成知识、体验、表达与反思。'],['04','红色叙事体验','通过剧本杀与角色演绎，理解历史与家国情怀。'],['05','移动美育巴士','探索流动展厅与课堂，拓展红色美育的传播场景。']].map(([n,title,text])=>`<article class="five-item"><b>${n}</b><h3>${title}</h3><p>${text}</p></article>`).join('')}</div><p class="fine-print" style="margin-top:16px">“X”指高校、景区、村民、手艺人、企业及公共文化机构等合作主体；移动美育巴士是连接校园与社区的流动课堂方案。</p></section>
  <section class="content-block"><h2>已有实践与成果</h2><div class="outcome-grid"><article class="outcome"><strong>300</strong><p>份有效问卷<br>项目田野调研记录</p></article><article class="outcome"><strong>300</strong><p>名学生<br>通识课程教学覆盖</p></article><article class="outcome"><strong>2000+</strong><p>人次<br>小学红色文化宣讲覆盖</p></article></div><p class="fine-print">通过田野调研、通识课程与校园宣讲，持续探索红色文化的青年表达与美育实践。</p><ul class="content-list"><li>已在南京农业大学《音乐鉴赏》通识核心课中作为教学模块使用。</li><li>荣获南京农业大学“振兴杯”创新创业大赛青年红色筑梦之旅赛道三等奖。</li><li>开展沙家浜红色文化进校园宣讲，记录脸谱绘制、绘画、角色演绎与学生反馈。</li></ul><a class="arrow-link" href="#stories">阅读美育实践记录 <span aria-hidden="true">↗</span></a></section>
  <section class="content-block"><h2>一次体验，看见学生的变化</h2><p class="muted">通过 30 名参与者的活动前后测，观察文化认知、学习意愿与故事表达的变化。</p><div class="chart-legend" style="margin-top:20px"><span>活动前</span><span>活动后</span></div><div class="result-bars" role="img" aria-label="30 人前后测：识别脸谱色彩含义从 27% 到 83%；愿意主动了解红色文化从 34% 到 76%；能讲述沙家浜历史故事从 15% 到 68%。"><div class="result-bar"><span>识别脸谱色彩含义</span><div><i style="width:27%">27%</i><i class="after" style="width:83%">83%</i></div></div><div class="result-bar"><span>愿意主动了解文化</span><div><i style="width:34%">34%</i><i class="after" style="width:76%">76%</i></div></div><div class="result-bar"><span>自己讲述历史故事</span><div><i style="width:15%">15%</i><i class="after" style="width:68%">68%</i></div></div></div><div class="table-scroll"><table class="results-table"><caption class="visually-hidden">学生红色文化与京剧知识学习前后测数据，N = 30</caption><thead><tr><th scope="col">观察项</th><th scope="col">活动前</th><th scope="col">活动后</th><th scope="col">变化</th></tr></thead><tbody><tr><th scope="row">识别京剧脸谱颜色含义</th><td>27%</td><td>83%</td><td>+56 个百分点</td></tr><tr><th scope="row">愿意主动了解红色文化</th><td>34%</td><td>76%</td><td>+42 个百分点</td></tr><tr><th scope="row">能用自己的话讲述沙家浜故事</th><td>15%</td><td>68%</td><td>+53 个百分点</td></tr></tbody></table></div><p class="fine-print">本次前后测样本量为 30 人。变化按前后占比之差，以“百分点”呈现。</p></section>
  <section class="content-block"><h2>接下来，把课程做得更完整</h2><ul class="content-list"><li>完成《沙家浜·青春版》沉浸式剧本杀课程包，包括完整剧本、角色卡、道具清单与场景指南。</li><li>完成四季研学课程包，每季配套 90 分钟主题教案、物料清单、安全须知与学生工作纸。</li><li>继续开展调研，计划有效样本不少于 500 份、深度访谈不少于 5 次，形成完整研究报告。</li><li>探索研究论文、竞赛申报，以及高校、景区与在地文化机构的持续合作。</li></ul><p class="fine-print">上述课程包与研究成果将在后续项目实践中逐步完善。</p></section>
  <section class="content-block" id="materials"><h2>项目研究资料</h2><p class="muted" style="margin-bottom:25px">探索项目的研究背景、创新模式与实践方案，点击图片可放大阅读。</p><div class="source-gallery">${[[2,'问题提出'],[3,'案例验证与研究立题'],[4,'政策引领与美育机遇'],[5,'理论基础'],[7,'问题归因'],[8,'创新模式'],[12,'研究结论与项目展望']].map(([number,title])=>`<article class="source-card"><button data-slide="${number}" data-title="${title}" aria-label="放大查看${title}"><img src="${asset(`slide-${String(number).padStart(2,'0')}.webp`)}" alt="项目研究资料：${title}" loading="lazy"><p>${String(number).padStart(2,'0')} / ${title} <span aria-hidden="true">↗</span></p></button></article>`).join('')}</div><p class="page-bottom-note">以青年视角重构文化表达，通过内容创新、场景联动与多方协作，让红色美育持续走进生活。</p></section></div>`;}
function storiesPage(){return `${pageHeading('美育足迹','从田野里的真实对话，到课堂里的创意表达。记录每一次靠近文化、理解历史与发现美的过程。','OUR FOOTPRINTS')}<section class="container page-content"><article class="story-lead"><div><p class="eyebrow">田野里的相遇</p><h2>老故事，<br>从新的对话开始。</h2><p>团队走进沙家浜，听商户谈生活、听文化工作者谈传承，也听青年讲述他们期待的体验。研究与实践，在这些具体的声音中生长。</p><button class="button primary" data-story="fieldwork">阅读调研故事 <span aria-hidden="true">↗</span></button></div><img src="${asset('interview.webp')}" alt="项目团队访谈沙家浜文化工作者"></article><div class="pills" style="margin-bottom:29px" aria-label="足迹分类">${['全部足迹','田野调研','创意表达','校园实践'].map(category=>`<button class="pill" data-story-category="${category}" aria-pressed="${storyCategory===category}">${category}</button>`).join('')}</div><div class="stories-grid" id="stories-grid">${stories.filter(story=>storyCategory==='全部足迹'||story.category===storyCategory).map(storyCard).join('')}</div><p class="page-bottom-note">记录田野里的相遇、课堂里的发现与创作中的表达，让每一次美育实践留下回响。</p></section>`;}
function renderRoute(resetScroll=true){const requested=location.hash.slice(1).split('?')[0]||'home';route=['home','shop','activities','project','stories'].includes(requested)?requested:'home';main.innerHTML=({home:homePage,shop:shopPage,activities:activitiesPage,project:projectPage,stories:storiesPage})[route]();document.title=`${({home:'沙家浜红色美育',shop:'文创商城',activities:'活动预约',project:'走近项目',stories:'美育足迹'})[route]} · 芦荡薪火`;document.querySelectorAll('[data-nav]').forEach(link=>{if(link.dataset.nav===route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');if(route==='shop')renderCatalog();if(route==='activities')renderSeason();if(resetScroll)window.scrollTo({top:0,behavior:'instant'});}
function openProduct(id){const product=products.find(item=>item.id===id);if(!product)return;currentProduct=product;productVariant=product.variants[0];productQuantity=1;renderProduct();}
function renderProduct(){const product=currentProduct;openModal(product.name,`<div class="product-detail"><img src="${asset(product.image)}" alt="${product.name}设计展示"><div><span class="mini-label">${product.categories.join(' / ')}</span><h3>${product.subtitle}</h3><p>${product.description}</p><span class="price">¥${product.price}<small>${priceLabel()}</small></span><span class="fine-print">选择款式</span><div class="variant-options">${product.variants.map(variant=>`<button class="pill" data-variant="${variant}" aria-pressed="${variant===productVariant}">${variant}</button>`).join('')}</div><p><strong>美育小提示：</strong>${product.goal}</p><div class="detail-bottom"><div class="quantity-control"><button data-product-qty="-1" aria-label="减少商品数量">−</button><input id="product-quantity" aria-label="商品数量" type="number" min="1" max="99" value="${productQuantity}"><button data-product-qty="1" aria-label="增加商品数量">+</button></div><button class="button primary small" data-add-cart>加入购物袋</button></div></div></div><div class="notice">${product.note} ${config.mode==='demo'?'当前仅支持生成演示订单草稿，不收款、不发货。':''}</div>`);}
function addToCart(){const quantity=Number($('#product-quantity').value);if(!Number.isInteger(quantity)||quantity<1||quantity>99){toast('请选择 1–99 件商品');return;}const item=cart.find(item=>item.id===currentProduct.id&&item.variant===productVariant);if(item){if(item.quantity+quantity>99){toast('同一款式最多选择 99 件');return;}item.quantity+=quantity;}else cart.push({id:currentProduct.id,variant:productVariant,quantity});saveCart();modal.close();toast(`${currentProduct.name}已加入购物袋`);}
function totalCart(){return cart.reduce((sum,item)=>sum+products.find(product=>product.id===item.id).price*item.quantity,0);}
function renderCart(){cartDialog.innerHTML=`<header class="modal-header"><h2 id="cart-title">我的购物袋 <small class="fine-print">${cart.reduce((sum,item)=>sum+item.quantity,0)} 件</small></h2><button class="close-modal" data-close="cart" aria-label="关闭购物袋">×</button></header><div class="modal-body">${cart.length?cart.map((item,index)=>{const product=products.find(product=>product.id===item.id);return `<article class="cart-item"><img src="${asset(product.image)}" alt="${product.name}"><div><h3>${product.name}</h3><p>${item.variant}</p><div class="item-controls"><span class="price">${money(product.price)}</span><div class="quantity-control"><button data-cart-qty="${index}" data-delta="-1" aria-label="减少${product.name}数量" ${item.quantity===1?'disabled':''}>−</button><input type="number" min="1" max="99" data-cart-input="${index}" value="${item.quantity}" aria-label="${product.name}数量"><button data-cart-qty="${index}" data-delta="1" aria-label="增加${product.name}数量" ${item.quantity===99?'disabled':''}>+</button></div></div></div><button class="remove-item" data-remove="${index}" aria-label="移除${product.name}">×</button></article>`;}).join(''):`<div class="empty-state"><h3>购物袋里，等一份京韵</h3><p>挑选喜欢的文创，把文化记忆带回家。</p><button class="button primary" data-shop-link>去逛逛商城</button></div>`}${cart.length?`<div class="cart-total"><span>商品${config.mode==='demo'?'参考':''}合计</span><span class="price">${money(totalCart())}</span></div><p class="fine-print" style="margin-bottom:22px">${config.mode==='demo'?'演示参考价，不包含配送费用。正式价格和库存待确认。':'运费、库存与最终金额由订单服务确认。'}</p><div class="cart-buttons"><button class="button primary full" data-checkout>${config.mode==='demo'?'填写订单草稿':'填写订单信息'} <span aria-hidden="true">→</span></button><button class="button light full" data-close="cart">继续浏览</button></div>`:''}<div class="notice">${config.mode==='demo'?'购物袋仅保存在本浏览器。收货信息不会存入浏览器长期存储，也不会发送至运营方。':'购物袋保存在本浏览器；提交订单会将必要的收货信息发送至运营方。'}</div></div>`;if(!cartDialog.open)cartDialog.showModal();}
function openCheckout(){if(!cart.length)return;cartDialog.close();checkout={id:makeId('order'),step:1,name:'',phone:'',address:'',notes:'',consent:false,busy:false,items:cart.map(item=>({...item})),total:totalCart()};renderCheckout();}
function makeId(prefix){return `${prefix}-${crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`}`;}
function field(name,label,type='text',value='',attrs='',help=''){return `<div class="field ${name==='address'||name==='notes'?'wide':''}"><label for="${name}">${label}<span class="required">*</span></label><input id="${name}" name="${name}" type="${type}" value="${escape(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</div>`;}
function renderCheckout(){if(checkout.step===1)openModal('填写订单信息',`<p class="fine-print">${config.mode==='demo'?'填写后生成订单草稿，不会真实下单。':'请填写收货信息，提交前可核对订单。'}</p><form id="checkout-form"><div class="form-grid" style="margin-top:20px">${field('name','收货人','text',checkout.name,'required maxlength="30" autocomplete="name"')}${field('phone','联系电话','tel',checkout.phone,'required maxlength="20" autocomplete="tel" inputmode="tel"')}${field('address','收货地址','text',checkout.address,'required maxlength="200" autocomplete="street-address"')}<div class="field wide"><label for="notes">备注（选填）</label><textarea id="notes" name="notes" maxlength="300">${escape(checkout.notes)}</textarea></div></div><label class="checkbox-label"><input type="checkbox" name="consent" required ${checkout.consent?'checked':''}><span>${config.mode==='demo'?'我了解这是订单草稿，信息仅用于本次演示，不会发送或收款。':'我同意将收货信息发送至运营方，用于订单处理。'}</span></label><p id="checkout-error" class="form-error" role="alert"></p><div class="wizard-footer"><button type="button" class="button light" data-return-cart>返回购物袋</button><button class="button primary" type="submit">核对订单 <span aria-hidden="true">→</span></button></div></form>`);else openModal('核对订单',`<dl class="review-table"><dt>收货人</dt><dd>${escape(checkout.name)}</dd><dt>联系电话</dt><dd>${escape(checkout.phone)}</dd><dt>收货地址</dt><dd>${escape(checkout.address)}</dd><dt>商品</dt><dd>${checkout.items.map(item=>`${products.find(p=>p.id===item.id).name} · ${escape(item.variant)} × ${item.quantity}`).join('<br>')}</dd>${checkout.notes?`<dt>备注</dt><dd>${escape(checkout.notes)}</dd>`:''}</dl><div class="review-total"><span>${config.mode==='demo'?'演示参考合计':'商品金额（待服务确认）'}</span><span class="price">${money(checkout.total)}</span></div><div class="payment-option selected">${config.mode==='demo'?'生成订单草稿':'提交订单'}<small>${config.mode==='demo'?'不收款、不发货。草稿可下载留存。':'库存、价格和运费将由订单服务再次核验。'}</small></div><p id="checkout-error" class="form-error" role="alert"></p><div class="wizard-footer"><button class="button light" data-checkout-back ${checkout.busy?'disabled':''}>返回修改</button><button class="button primary" data-order-submit ${checkout.busy?'disabled':''}>${checkout.busy?'正在提交…':config.mode==='demo'?'生成订单草稿':'提交订单'}</button></div>`);}
function demoDates(activityId){const dates=[];const months={spring:[3,4,5],summer:[6,7,8],autumn:[9,10,11],winter:[12,1,2]};for(let offset=1;offset<=370&&dates.length<12;offset++){const value=addDays(today(),offset);const date=new Date(`${value}T12:00:00+08:00`);const weekday=date.getUTCDay();const month=date.getUTCMonth()+1;if((weekday===6||weekday===0)&&(!months[activityId]||months[activityId].includes(month)))dates.push(value);}return dates;}
function availableDates(activityId){if(config.mode==='demo')return demoDates(activityId);return [...new Set(config.liveSchedule.filter(item=>item.activityId===activityId&&item.date>=today()).map(item=>item.date))].sort();}
function timeSlots(activityId,date){if(config.mode==='demo')return [{id:'morning',time:'09:30–11:30'},{id:'afternoon',time:'14:00–16:00'},{id:'evening',time:'18:30–20:30'}];return config.liveSchedule.filter(item=>item.activityId===activityId&&item.date===date).map(item=>({id:item.id,time:item.time}));}
function openBooking(id){const activity=activities.find(item=>item.id===id);wizard={id:makeId('booking'),step:activity?2:1,activityId:activity?.id||'script',format:'day',date:'',slot:'',group:'学生专场',age:'18–25 岁',people:5,name:'',phone:'',organization:'',notes:'',consent:false,busy:false};renderWizard();}
function selectedActivity(){return activities.find(activity=>activity.id===wizard.activityId);}
function bookingTotal(){const activity=selectedActivity();return activity.price*wizard.people*(activity.type==='study'&&wizard.format==='series'?4:1);}
function steps(){return `<ol class="steps" aria-label="预约进度">${['选择项目','课程与目标','时间与人数','报名信息','核对并提交'].map((label,index)=>`<li class="${index+1===wizard.step?'active':index+1<wizard.step?'complete':''}" ${index+1===wizard.step?'aria-current="step"':''}><span>${index+1<wizard.step?'✓':index+1}</span>${label}</li>`).join('')}</ol>`;}
function wizardFooter(){return `<div class="wizard-footer"><button type="button" class="button light" data-wizard-back ${wizard.busy?'disabled':''}>${wizard.step===1?'取消':'上一步'}</button><div><span class="fine-print">${config.mode==='demo'?'流程演示 · 不收款':''}</span><button ${wizard.step===3||wizard.step===4?'type="submit"':'type="button"'} class="button primary" ${wizard.step===5?'data-booking-submit':'data-wizard-next'} ${wizard.busy?'disabled':''}>${wizard.busy?'正在提交…':wizard.step===5?(config.mode==='demo'?'生成预约草稿':'提交预约'):'下一步'} <span aria-hidden="true">→</span></button></div></div>`;}
function renderWizard(){const activity=selectedActivity();let content=steps();
  if(wizard.step===1)content+=`<h3 style="margin-top:0">选择一段属于你的美育旅程</h3><p class="fine-print" style="margin-bottom:19px">沉浸式故事体验，或跟着四季走进课堂。</p><div class="activity-options">${activities.map(item=>`<button class="activity-option" data-booking-activity="${item.id}" aria-pressed="${wizard.activityId===item.id}"><span>${item.eyebrow}</span><b>${item.name}</b><span>${item.duration}</span></button>`).join('')}</div>${wizardFooter()}`;
  if(wizard.step===2)content+=`<div class="intro-detail"><img src="${asset(activity.image)}" alt="${activity.name}课程图"><div><span class="mini-label">${activity.eyebrow}</span><h3>${activity.name}</h3><p>${activity.description}</p></div></div><h3>这次体验，学会什么？</h3><ul class="learning-goals">${activity.goals.map(goal=>`<li>${goal}</li>`).join('')}</ul><div class="outline-list">${activity.outline.map((item,index)=>`<span>${index+1}. ${item}</span>`).join('')}</div><p class="fine-print">${activity.source}</p>${wizardFooter()}`;
  if(wizard.step===3){const dates=availableDates(activity.id);if(!dates.includes(wizard.date)){wizard.date=dates[0]||'';wizard.slot='';}const slots=timeSlots(activity.id,wizard.date);if(!slots.some(slot=>slot.id===wizard.slot))wizard.slot=slots[0]?.id||'';const ageOptions=wizard.group==='学生专场'?['8–12 岁','13–17 岁','18–25 岁']:['18–40 岁','41 岁及以上','成人混合年龄'];if(!ageOptions.includes(wizard.age))wizard.age=ageOptions[0];content+=`<form id="schedule-form"><div class="form-grid"><div class="field"><label for="booking-date">${activity.type==='study'&&wizard.format==='series'?'系列课首场日期':'活动日期'}<span class="required">*</span></label><select id="booking-date" name="date" required ${dates.length?'':'disabled'}>${dates.length?dates.map(value=>`<option value="${value}" ${value===wizard.date?'selected':''}>${dateText(value)}${config.mode==='demo'?' · 演示':''}</option>`).join(''):'<option value="">暂无可预约日期</option>'}</select><small>${config.mode==='demo'?'日期为自动生成的周末示例，无真实名额。':'仅展示运营方公布的场次。'}</small></div><div class="field"><label for="booking-people">参与人数<span class="required">*</span></label><input id="booking-people" name="people" type="number" min="1" max="${activity.type==='script'?30:50}" value="${wizard.people}" required inputmode="numeric"><small>${activity.type==='script'?'5 人一组；不足 5 人可提出拼组意向。':'含所有参加活动的学生与成人。'}</small></div><div class="field"><label for="booking-group">参与场次类型<span class="required">*</span></label><select id="booking-group" name="group"><option ${wizard.group==='学生专场'?'selected':''}>学生专场</option><option ${wizard.group==='成人社区场'?'selected':''}>成人社区场</option></select></div><div class="field"><label for="booking-age">年龄段<span class="required">*</span></label><select id="booking-age" name="age">${ageOptions.map(value=>`<option ${value===wizard.age?'selected':''}>${value}</option>`).join('')}</select></div>${activity.type==='study'?`<div class="field wide"><label for="booking-format">课程形式<span class="required">*</span></label><select id="booking-format" name="format"><option value="day" ${wizard.format==='day'?'selected':''}>单日营 · 一次主题体验</option><option value="series" ${wizard.format==='series'?'selected':''}>系列课 · 4 次主题学习</option></select><small>主题课为 90 分钟。系列课完整营期与具体安排待确认，演示版按 4 次计算参考费用。</small></div>`:''}<div class="field wide"><span>选择场次<span class="required">*</span></span><div class="time-grid" aria-label="活动场次">${slots.map(slot=>`<button class="time-option" type="button" data-slot="${escape(slot.id)}" aria-pressed="${slot.id===wizard.slot}">${escape(slot.time)}<small>${config.mode==='demo'?'演示场次':'可提交预约'}</small></button>`).join('')}</div></div></div><p id="wizard-error" class="form-error" role="alert"></p>${wizardFooter()}</form>`;}
  if(wizard.step===4)content+=`<form id="registration-form"><h3 style="margin-top:0">留下报名信息</h3><p class="fine-print" style="margin-bottom:20px">${config.mode==='demo'?'信息仅保留在当前弹窗中，不会自动保存或发送。':'信息将用于联系您确认预约。'}</p><div class="form-grid">${field('booking-name','联系人','text',wizard.name,'required maxlength="30" autocomplete="name"')}${field('booking-phone','联系电话','tel',wizard.phone,'required maxlength="20" autocomplete="tel" inputmode="tel"')}<div class="field wide"><label for="booking-organization">学校 / 社区 / 机构（选填）</label><input id="booking-organization" name="organization" maxlength="100" value="${escape(wizard.organization)}" autocomplete="organization"></div><div class="field wide"><label for="booking-notes">补充需求（选填）</label><textarea id="booking-notes" name="notes" maxlength="300" placeholder="如拼组意向、带队安排或课程需求">${escape(wizard.notes)}</textarea><small>请勿填写身份证、银行卡或儿童个人证件信息。</small></div></div><label class="checkbox-label"><input name="consent" type="checkbox" required ${wizard.consent?'checked':''}><span>${config.mode==='demo'?'我了解当前为演示流程，草稿不会发送，也不会锁定名额或产生付款。':'我同意将报名信息发送至运营方，用于处理预约。'} 未成年人报名须由监护人或授权带队人员填写。</span></label><p id="wizard-error" class="form-error" role="alert"></p>${wizardFooter()}</form>`;
  if(wizard.step===5){const selectedSlot=timeSlots(activity.id,wizard.date).find(item=>item.id===wizard.slot);content+=`<h3 style="margin-top:0">核对这次美育之旅</h3><dl class="review-table"><dt>预约项目</dt><dd>${activity.eyebrow} · ${activity.name}</dd><dt>参与日期</dt><dd>${dateText(wizard.date)}</dd><dt>活动场次</dt><dd>${escape(selectedSlot?.time||'待确认')}</dd><dt>参与者</dt><dd>${wizard.group} · ${wizard.age} · ${wizard.people} 人</dd>${activity.type==='study'?`<dt>课程形式</dt><dd>${wizard.format==='series'?'系列课 · 4 次主题课':'单日营'}${wizard.format==='series'?'（后续日期待确认）':''}</dd>`:''}<dt>联系人</dt><dd>${escape(wizard.name)} · ${escape(wizard.phone)}</dd>${wizard.organization?`<dt>学校 / 社区</dt><dd>${escape(wizard.organization)}</dd>`:''}${wizard.notes?`<dt>补充需求</dt><dd>${escape(wizard.notes)}</dd>`:''}</dl><div class="review-total"><span>${config.mode==='demo'?'演示参考费用':'参考费用（服务核验后确认）'} / ${wizard.people} 人${activity.type==='study'&&wizard.format==='series'?' × 4 次':''}</span><span class="price">${money(bookingTotal())}</span></div><div class="payment-options"><div class="payment-option selected">${config.mode==='demo'?'生成预约意向草稿':'提交预约，等待运营确认'}<small>${config.mode==='demo'?'可下载报名信息，暂不发送至运营方。':'预约结果以服务返回的确认信息为准。'}</small></div><div class="payment-option"><span class="muted">在线支付</span><small>${config.mode==='demo'?'尚未开通，无需付款。':'由运营方确认费用后提供付款方式。'}</small></div></div><p id="wizard-error" class="form-error" role="alert"></p>${wizardFooter()}`;}
  openModal('预约美育体验',content);
}
function captureSchedule(){if(!wizard||wizard.step!==3)return;const form=$('#schedule-form');if(!form)return;const data=new FormData(form);wizard.date=String(data.get('date')||'');wizard.people=Number(data.get('people'));wizard.group=String(data.get('group')||'学生专场');wizard.age=String(data.get('age')||'');wizard.format=String(data.get('format')||'day');}
function captureRegistration(){if(!wizard||wizard.step!==4)return;const form=$('#registration-form');if(!form)return;wizard.name=$('#booking-name').value;wizard.phone=$('#booking-phone').value;wizard.organization=$('#booking-organization').value;wizard.notes=$('#booking-notes').value;wizard.consent=form.elements.consent.checked;}
function validPhone(value){return /^\+?[\d\s()-]{7,20}$/.test(value)&&value.replace(/\D/g,'').length>=7;}
function validateRegistration(name,phone){if(!name.trim())return '请填写联系人姓名。';if(!validPhone(phone.trim()))return '请填写有效的联系电话（至少 7 位数字）。';return '';}
function courseModal(id){const activity=activities.find(item=>item.id===id);if(!activity)return;openModal(`${activity.name} · 美育目标`,`<div class="intro-detail"><img src="${asset(activity.image)}" alt="${activity.name}项目素材"><div><h3>${activity.eyebrow}</h3><p>${activity.description}</p></div></div><ul class="learning-goals">${activity.goals.map(goal=>`<li>${goal}</li>`).join('')}</ul><p class="fine-print">${activity.source}</p><div class="wizard-footer"><button class="button light" data-close="modal">关闭</button><button class="button primary" data-book="${activity.id}">选择时间 <span aria-hidden="true">→</span></button></div>`);}
async function sendRequest(endpoint,payload){if(!endpoint)throw new Error('正式提交服务尚未配置。');const url=new URL(endpoint,location.href);if(url.protocol!=='https:')throw new Error('提交接口必须使用 HTTPS。');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),config.requestTimeoutMs);try{const response=await fetch(url.href,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':payload.requestId},body:JSON.stringify(payload),signal:controller.signal,credentials:'omit'});if(!response.ok)throw new Error(response.status===409?'该场次或商品已变更，请重新选择。':'提交未完成，请稍后重试。');const result=await response.json();if(!['accepted','pending','confirmed'].includes(result.status)||typeof result.reference!=='string'||!result.reference.trim())throw new Error('服务未返回有效确认结果，请联系运营方。');return result;}catch(error){if(error.name==='AbortError')throw new Error('请求超时。请重试，系统会使用同一编号避免重复提交。');throw error;}finally{clearTimeout(timer);}}
async function submitBooking(){if(!wizard||wizard.busy)return;const activity=selectedActivity();const payload={requestId:wizard.id,kind:'booking',activityId:activity.id,activityName:activity.name,date:wizard.date,slotId:wizard.slot,group:wizard.group,ageRange:wizard.age,participants:wizard.people,format:activity.type==='study'?wizard.format:'script',contact:{name:wizard.name.trim(),phone:wizard.phone.trim(),organization:wizard.organization.trim()},notes:wizard.notes.trim(),referenceAmount:bookingTotal(),currency:'CNY',mode:config.mode};if(!availableDates(activity.id).includes(wizard.date)||!timeSlots(activity.id,wizard.date).some(slot=>slot.id===wizard.slot)){wizard.step=3;renderWizard();$('#wizard-error').textContent='原场次已过期，请重新选择日期和时间。';return;}if(config.mode==='demo'){lastDraft={...payload,status:'draft',createdAt:new Date().toISOString()};showResult('booking',false);return;}wizard.busy=true;renderWizard();try{const result=await sendRequest(config.bookingEndpoint,payload);lastDraft={...payload,status:result.status,reference:result.reference,createdAt:new Date().toISOString()};showResult('booking',true);}catch(error){wizard.busy=false;renderWizard();$('#wizard-error').textContent=error.message;}}
async function submitOrder(){if(!checkout||checkout.busy)return;const payload={requestId:checkout.id,kind:'order',items:checkout.items,contact:{name:checkout.name.trim(),phone:checkout.phone.trim(),address:checkout.address.trim()},notes:checkout.notes.trim(),referenceAmount:checkout.total,currency:'CNY',mode:config.mode};if(config.mode==='demo'){lastDraft={...payload,status:'draft',createdAt:new Date().toISOString()};showResult('order',false);return;}checkout.busy=true;renderCheckout();try{const result=await sendRequest(config.orderEndpoint,payload);lastDraft={...payload,status:result.status,reference:result.reference,createdAt:new Date().toISOString()};showResult('order',true);}catch(error){checkout.busy=false;renderCheckout();$('#checkout-error').textContent=error.message;}}
function showResult(kind,submitted){const name=kind==='booking'?'预约':'订单';openModal(submitted?`${name}提交结果`:`${name}草稿`, `<div class="draft-success"><div class="success-icon" aria-hidden="true">✓</div><h3>${submitted?(lastDraft.status==='confirmed'?`${name}已确认`:`${name}申请已收到`):`${name}草稿已生成`}</h3><p>${submitted?`服务返回编号：${escape(lastDraft.reference)}。${lastDraft.status==='confirmed'?'请按运营方安排参与或收货。':'请等待运营方进一步确认。'}`:`这份草稿记录了您的${kind==='booking'?'活动选择与报名':'商品与收货'}信息。当前没有发送至运营方，${kind==='booking'?'没有锁定名额':'没有真实下单'}，也没有产生付款。`}</p><button class="button primary" data-download-draft>下载${name}${submitted?'记录':'草稿'} <span aria-hidden="true">↓</span></button><button class="button light" data-close="modal">完成</button><p class="fine-print">关闭后，个人信息不会保存在本浏览器。下载文件请妥善保管。</p></div>`);wizard=null;checkout=null;}
function downloadDraft(){if(!lastDraft)return;const lines=[`芦荡薪火 · ${lastDraft.kind==='booking'?'预约':'订单'}${lastDraft.status==='draft'?'意向草稿':'记录'}`,`状态：${lastDraft.status==='draft'?'草稿，未发送、未付款、未确认':lastDraft.status}`,`编号：${lastDraft.reference||lastDraft.requestId}`,`生成时间：${new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(new Date(lastDraft.createdAt))}`,''];if(lastDraft.kind==='booking'){const activity=activities.find(a=>a.id===lastDraft.activityId);const slot=timeSlots(activity.id,lastDraft.date).find(s=>s.id===lastDraft.slotId);lines.push(`项目：${lastDraft.activityName}`,`日期：${dateText(lastDraft.date)}`,`场次：${slot?.time||lastDraft.slotId}`,`人数：${lastDraft.participants}`,`年龄段：${lastDraft.ageRange}`,`参与类型：${lastDraft.group}`,`课程形式：${lastDraft.format==='series'?'系列课（4 次；后续日期待确认）':lastDraft.format==='day'?'单日营':'剧本杀'}`,`联系人：${lastDraft.contact.name}`,`电话：${lastDraft.contact.phone}`,`学校/社区：${lastDraft.contact.organization||'未填写'}`);}else{lines.push(...lastDraft.items.map(item=>{const product=products.find(p=>p.id===item.id);return `${product.name} / ${item.variant} × ${item.quantity} = ${money(product.price*item.quantity)}（参考）`;}),`收货人：${lastDraft.contact.name}`,`电话：${lastDraft.contact.phone}`,`地址：${lastDraft.contact.address}`);}lines.push(`备注：${lastDraft.notes||'无'}`,`参考费用：${money(lastDraft.referenceAmount)}`,lastDraft.status==='draft'?'说明：该文件仅为本地流程演示草稿。费用及时间为示例，运营方未收到申请。':'说明：交付与活动安排以运营方最终通知为准。');const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`芦荡薪火-${lastDraft.kind==='booking'?'预约':'订单'}-${lastDraft.requestId.slice(-8)}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('草稿已开始下载');}
function showInfo(type){const information={
  privacy:['隐私说明',`<div class="prose"><h3>当前演示版</h3><p>购物袋只在当前浏览器的本地存储中保存商品编号、款式与数量。网站不保存联系人、电话、收货地址等个人信息到本地存储。</p><p>报名和订单信息只保留在当前弹窗的内存中。${config.mode==='demo'?'不会发送至运营方或任何服务器。':'正式提交时，必要信息会发送到运营方配置的接口。'}关闭弹窗后会清除草稿中的个人信息。</p><p>您可以主动下载文本草稿。下载的文件含您填写的信息，请妥善保管。</p><p>请勿填写身份证、银行卡或其他证件资料。未成年人报名须由监护人或授权带队人员填写。</p></div>`],
  faq:['常见问题',`<div class="faq-body"><details open><summary>目前可以购买商品吗？</summary><p>${config.mode==='demo'?'当前展示商品概念、参考价格与购物流程，可生成订单草稿；暂不收款或发货。':'请通过商城提交订单，并等待运营方确认库存与配送。'}</p></details><details><summary>预约是否会自动获得名额？</summary><p>${config.mode==='demo'?'演示版没有真实名额，生成草稿不会完成正式预约。':'提交申请后，以服务与运营方确认结果为准。'}</p></details><details><summary>课程内容来自哪里？</summary><p>课程以沙家浜红色历史、京剧艺术与四季自然生态为基础，融合文化讲解、角色体验与创意表达，连接知识学习和亲身实践。</p></details><details><summary>可以安排学校或社区团体活动吗？</summary><p>预约表单支持填写学校或社区名称与团体需求。具体人数、地点、带队和时间需由运营方确认。</p></details></div>`],
  cooperation:['共同参与，让美育走得更远',`<div class="prose"><p>项目以高校、景区、社区与在地文化工作者为合作主体，探索课程共建、校园宣讲、文化体验与研学活动。</p><ul class="content-list"><li>学校：主题课程、教学模块与学生实践。</li><li>社区：成人体验、亲子活动与文化交流。</li><li>文化机构：内容共创、传统艺术与在地技艺体验。</li></ul><div class="notice">${config.contactEmail?`合作邮箱：<a class="inline-link" href="mailto:${escape(config.contactEmail)}">${escape(config.contactEmail)}</a>`:'正式合作联系方式尚未提供。您可以在预约草稿中填写机构名称与合作需求，待运营方公布接收方式后联系。'}</div><button class="button primary" data-book="">填写活动意向 <span aria-hidden="true">↗</span></button></div>`],
};const info=information[type];if(info)openModal(info[0],info[1]);}

document.addEventListener('click',event=>{
  const button=event.target.closest('button,a');if(!button)return;
  if(button.matches('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView({behavior:'instant'});return;}
  if(button.hasAttribute('data-section')){const section=button.dataset.section;setTimeout(()=>document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'}),60);}
  if(button.matches('.menu-toggle')){const nav=$('#mobile-nav');nav.hidden=!nav.hidden;button.setAttribute('aria-expanded',String(!nav.hidden));button.setAttribute('aria-label',nav.hidden?'打开导航':'关闭导航');}
  if(button.matches('.cart-toggle'))renderCart();
  if(button.hasAttribute('data-close')){if(button.dataset.close==='modal'&&(wizard?.busy||checkout?.busy)){toast('正在提交，请稍候');return;}(button.dataset.close==='cart'?cartDialog:modal).close();}
  if(button.hasAttribute('data-info'))showInfo(button.dataset.info);
  if(button.hasAttribute('data-product'))openProduct(button.dataset.product);
  if(button.hasAttribute('data-variant')){productQuantity=Number($('#product-quantity').value)||1;productVariant=button.dataset.variant;renderProduct();}
  if(button.hasAttribute('data-product-qty')){const input=$('#product-quantity');productQuantity=Math.min(99,Math.max(1,(Number(input.value)||1)+Number(button.dataset.productQty)));input.value=productQuantity;}
  if(button.hasAttribute('data-add-cart'))addToCart();
  if(button.hasAttribute('data-category')){shopCategory=button.dataset.category;document.querySelectorAll('[data-category]').forEach(node=>node.setAttribute('aria-pressed',String(node.dataset.category===shopCategory)));renderCatalog();}
  if(button.hasAttribute('data-reset-search')){shopCategory='全部文创';shopQuery='';shopSort='featured';renderRoute(false);}
  if(button.hasAttribute('data-season')){season=button.dataset.season;document.querySelectorAll('[data-season]').forEach(node=>node.setAttribute('aria-pressed',String(node.dataset.season===season)));renderSeason();}
  if(button.hasAttribute('data-story-category')){storyCategory=button.dataset.storyCategory;document.querySelectorAll('[data-story-category]').forEach(node=>node.setAttribute('aria-pressed',String(node.dataset.storyCategory===storyCategory)));$('#stories-grid').innerHTML=stories.filter(story=>storyCategory==='全部足迹'||story.category===storyCategory).map(storyCard).join('');}
  if(button.hasAttribute('data-story')){const story=stories.find(item=>item.id===button.dataset.story);openModal(story.title,`<img class="article-image" src="${asset(story.image)}" alt="${story.title}"><p class="mini-label">${story.category} / ${story.date}</p><div class="prose article-body">${story.paragraphs.map(text=>`<p>${text}</p>`).join('')}</div><p class="fine-print">芦荡薪火 · 美育实践记录</p>`);}
  if(button.hasAttribute('data-slide'))openModal(`项目研究资料 · ${button.dataset.title}`,`<img class="source-image" src="${asset(`slide-${String(button.dataset.slide).padStart(2,'0')}.webp`)}" alt="${escape(button.dataset.title)}"><p class="fine-print" style="margin-top:15px">${escape(button.dataset.title)} · 研究与实践方案</p><a class="arrow-link" target="_blank" rel="noopener" href="${asset(`slide-${String(button.dataset.slide).padStart(2,'0')}.webp`)}">打开原图放大查看 <span aria-hidden="true">↗</span></a>`);
  if(button.hasAttribute('data-course'))courseModal(button.dataset.course);
  if(button.hasAttribute('data-book'))openBooking(button.dataset.book);
  if(button.hasAttribute('data-booking-activity')){wizard.activityId=button.dataset.bookingActivity;wizard.date='';wizard.slot='';renderWizard();}
  if(button.hasAttribute('data-wizard-next')&&wizard&&wizard.step<3){wizard.step++;renderWizard();}
  if(button.hasAttribute('data-wizard-back')&&wizard&&!wizard.busy){captureSchedule();captureRegistration();if(wizard.step===1)modal.close();else{wizard.step--;renderWizard();}}
  if(button.hasAttribute('data-slot')){captureSchedule();wizard.slot=button.dataset.slot;document.querySelectorAll('[data-slot]').forEach(node=>node.setAttribute('aria-pressed',String(node.dataset.slot===wizard.slot)));}
  if(button.hasAttribute('data-booking-submit'))submitBooking();
  if(button.hasAttribute('data-cart-qty')){const item=cart[Number(button.dataset.cartQty)];item.quantity=Math.min(99,Math.max(1,item.quantity+Number(button.dataset.delta)));saveCart();renderCart();}
  if(button.hasAttribute('data-remove')){cart.splice(Number(button.dataset.remove),1);saveCart();renderCart();}
  if(button.hasAttribute('data-shop-link')){cartDialog.close();location.hash='shop';}
  if(button.hasAttribute('data-checkout'))openCheckout();
  if(button.hasAttribute('data-checkout-back')&&checkout&&!checkout.busy){checkout.step=1;renderCheckout();}
  if(button.hasAttribute('data-return-cart')){modal.close();renderCart();}
  if(button.hasAttribute('data-order-submit'))submitOrder();
  if(button.hasAttribute('data-download-draft'))downloadDraft();
});
document.addEventListener('input',event=>{if(event.target.id==='shop-search'){shopQuery=event.target.value;renderCatalog();}});
document.addEventListener('change',event=>{
  const target=event.target;
  if(target.id==='shop-sort'){shopSort=target.value;renderCatalog();}
  if(['booking-date','booking-group','booking-format'].includes(target.id)){captureSchedule();if(target.id==='booking-date')wizard.slot='';if(target.id==='booking-group')wizard.age=wizard.group==='学生专场'?'18–25 岁':'18–40 岁';renderWizard();}
  if(target.hasAttribute('data-cart-input')){const quantity=Number(target.value);if(!Number.isInteger(quantity)||quantity<1||quantity>99){toast('商品数量需为 1–99 的整数');renderCart();return;}cart[Number(target.dataset.cartInput)].quantity=quantity;saveCart();renderCart();}
});
document.addEventListener('submit',event=>{
  if(event.target.id==='schedule-form'){event.preventDefault();captureSchedule();const activity=selectedActivity();const max=activity.type==='script'?30:50;let error='';if(!availableDates(activity.id).includes(wizard.date))error='请选择可用日期。';if(!timeSlots(activity.id,wizard.date).some(slot=>slot.id===wizard.slot))error='请选择活动场次。';if(!Number.isInteger(wizard.people)||wizard.people<1||wizard.people>max)error=`参与人数需为 1–${max} 的整数。`;if(error){$('#wizard-error').textContent=error;return;}wizard.step=4;renderWizard();}
  if(event.target.id==='registration-form'){event.preventDefault();captureRegistration();const error=validateRegistration(wizard.name,wizard.phone)||(!wizard.consent?'请阅读并勾选信息使用说明。':'');if(error){$('#wizard-error').textContent=error;return;}wizard.step=5;renderWizard();}
  if(event.target.id==='checkout-form'){event.preventDefault();checkout.name=$('#name').value;checkout.phone=$('#phone').value;checkout.address=$('#address').value;checkout.notes=$('#notes').value;checkout.consent=event.target.elements.consent.checked;const error=validateRegistration(checkout.name,checkout.phone)||(!checkout.address.trim()?'请填写收货地址。':'')||(!checkout.consent?'请阅读并勾选信息使用说明。':'');if(error){$('#checkout-error').textContent=error;return;}checkout.step=2;renderCheckout();}
});
for(const dialog of [modal,cartDialog]){
  dialog.addEventListener('click',event=>{if(event.target===dialog){if(dialog===modal&&(wizard?.busy||checkout?.busy))return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
}
modal.addEventListener('cancel',event=>{if(wizard?.busy||checkout?.busy)event.preventDefault();});
modal.addEventListener('close',()=>{wizard=null;checkout=null;lastDraft=null;currentProduct=null;modal.innerHTML='';});
window.addEventListener('hashchange',()=>renderRoute());
$('#year').textContent=new Date().getFullYear();updateCartBadge();renderRoute(false);
